import { useState, useEffect, useMemo } from "react";
import { MapContainer, TileLayer, Popup, GeoJSON, useMapEvents, Polygon, Polyline, CircleMarker } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

const API_BASE = "http://localhost:8000";

function MapEvents({ drawingMode, currentPoints, setCurrentPoints }) {
    useMapEvents({
        click(e) {
            if (drawingMode) {
                const { lat, lng } = e.latlng;
                setCurrentPoints([...currentPoints, [lat, lng]]);
            }
        },
    });
    return null;
}

export default function AdminDashboard() {
    const navigate = useNavigate();
    const [activeTab, setActiveTab] = useState("territories");
    const [territories, setTerritories] = useState([]);
    const [allZones, setAllZones] = useState([]);
    
    const [selectedTerritoryId, setSelectedTerritoryId] = useState(null);
    const [showTerritoryForm, setShowTerritoryForm] = useState(false);
    const [newTerritoryName, setNewTerritoryName] = useState("");
    
    const [isDrawing, setIsDrawing] = useState(false);
    const [editingZoneId, setEditingZoneId] = useState(null);
    const [tempPoints, setTempPoints] = useState([]); 
    const [newZoneName, setNewZoneName] = useState("");

    const [assignDate, setAssignDate] = useState(new Date().toISOString().split('T')[0]);
const [availableSales, setAvailableSales] = useState([]);
const [selectedSalesIds, setSelectedSalesIds] = useState([]);
const [assignmentResult, setAssignmentResult] = useState(null); // { salesId: [zoneIds] }
const [isAssigning, setIsAssigning] = useState(false);
    // --- THÊM MỚI: State cho chức năng tải tự động ---
    const [searchDistrict, setSearchDistrict] = useState("");
    const [isFetching, setIsFetching] = useState(false);

    const [salesList, setSalesList] = useState([]);
    const [pendingSales, setPendingSales] = useState([]);
    const [showSalesForm, setShowSalesForm] = useState(false);
    const [editingSales, setEditingSales] = useState(null); // null = tạo mới, !null = chỉnh sửa
    const [salesFormData, setSalesFormData] = useState({
    username: "", email: "", password: "", full_name: "", phone: ""
    });

    useEffect(() => {
        refreshData();
    }, []);

    const refreshData = async () => {
        try {
            const [tRes, zRes, sRes, pRes] = await Promise.all([
                fetch(`${API_BASE}/territories`),
                fetch(`${API_BASE}/zones`),
                fetch(`${API_BASE}/admin/all-sales`),
                fetch(`${API_BASE}/admin/pending-sales`)
            ]);
            if (tRes.ok) setTerritories(await tRes.json());
            if (zRes.ok) setAllZones(await zRes.json());
            if (sRes.ok) setSalesList(await sRes.json());
            if (pRes.ok) setPendingSales(await pRes.json());
        } catch (e) { console.error("Lỗi tải dữ liệu:", e); }
    };

    // --- THÊM MỚI: Hàm xử lý tải phường tự động ---
    const handleAutoFetch = async () => {
        if (!selectedTerritoryId) return alert("Vui lòng chọn một Phân vùng trước!");
        if (!searchDistrict) return alert("Vui lòng nhập tên Quận (ví dụ: Quận Cầu Giấy)");
        
        setIsFetching(true);
        try {
            const res = await fetch(`${API_BASE}/admin/fetch-wards`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    district_name: searchDistrict,
                    territory_id: selectedTerritoryId
                })
            });
            
            if (res.ok) {
                alert("Tải dữ liệu các phường thành công!");
                setSearchDistrict("");
                refreshData(); 
            } else {
                const err = await res.json();
                alert("Lỗi: " + (err.detail || "Không tìm thấy dữ liệu. Hãy thử: 'Quận Cầu Giấy'"));
            }
        } catch (e) {
            alert("Lỗi kết nối server!");
        } finally {
            setIsFetching(false);
        }
    };

    // --- KHÔI PHỤC: Xử lý xóa phân vùng ---
    const handleDeleteTerritory = async (id) => {
        if (!window.confirm("Bạn có chắc chắn muốn xóa phân vùng này và toàn bộ dữ liệu liên quan?")) return;
        try {
            const res = await fetch(`${API_BASE}/territories/${id}`, { method: "DELETE" });
            if (res.ok) {
                if (selectedTerritoryId === id) setSelectedTerritoryId(null);
                refreshData();
            }
        } catch (e) { alert("Lỗi khi xóa phân vùng"); }
    };

    const handleCreateTerritory = async () => {
        if (!newTerritoryName) return;
        try {
            const res = await fetch(`${API_BASE}/territories`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name: newTerritoryName, zone_ids: [] })
            });
            if (res.ok) {
                setNewTerritoryName("");
                setShowTerritoryForm(false);
                refreshData();
            }
        } catch (e) { alert("Lỗi tạo phân vùng"); }
    };

    // --- SỬA LỖI: Xử lý Vẽ & Liên kết Zone với Territory ---
    const saveDrawnZone = async () => {
        if (tempPoints.length < 3) return alert("Cần ít nhất 3 điểm");
        if (!newZoneName) return alert("Vui lòng nhập tên vùng");

        const coords = [...tempPoints, tempPoints[0]].map(p => [p[1], p[0]]); 
        const geometry = { type: "Polygon", coordinates: [coords] };

        try {
            let res;
            if (editingZoneId) {
                // Cập nhật Zone cũ
                res = await fetch(`${API_BASE}/zones/${editingZoneId}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ name: newZoneName, geometry: geometry })
                });
            } else {
                // TẠO MỚI Zone
                res = await fetch(`${API_BASE}/zones`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        zone_code: `Z-${Date.now()}`,
                        name: newZoneName,
                        territory_id: Number(selectedTerritoryId), // Đã có liên kết ở đây
                        geometry: geometry,
                        center_lat: tempPoints[0][0],
                        center_lng: tempPoints[0][1],
                        num_customers: 0, num_orders: 0, revenue: 0
                    })
                });
            }
            
            if (!res.ok) {
                const errorData = await res.json();
                throw new Error(errorData.detail || "Lỗi từ Server");
            }

            alert("Lưu thành công!");
            setIsDrawing(false);
            setTempPoints([]);
            setEditingZoneId(null);
            setNewZoneName("");
            refreshData(); // Tải lại toàn bộ để cập nhật Map
        } catch (e) { 
            console.error("Chi tiết lỗi:", e);
            alert("Lỗi: " + e.message); 
        }
    };

    const deleteZone = async (zoneId) => {
        if (!window.confirm("Xóa vùng này?")) return;
        try {
            await fetch(`${API_BASE}/zones/${zoneId}`, { method: "DELETE" });
            refreshData();
        } catch (e) { alert("Lỗi khi xóa zone"); }
    };

    // --- SỬA LỖI: Logic lọc Zones (ép kiểu ID để so khớp chính xác) ---
    const activeZones = useMemo(() => {
        if (!selectedTerritoryId) return [];
        return allZones.filter(z => Number(z.territory_id) === Number(selectedTerritoryId));
    }, [selectedTerritoryId, allZones]);

    const getZoneColor = (index) => {
        const colors = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f', '#9b59b6', '#1abc9c', '#e67e22'];
        return colors[index % colors.length];
    };

    const handleSalesAction = async (action, id, data = null) => {
        try {
            let res;
            switch (action) {
                case 'approve':
                    res = await fetch(`${API_BASE}/admin/approve-user/${id}`, { method: "POST" });
                    break;
                case 'reject':
                case 'delete':
                    if (!window.confirm("Bạn có chắc chắn muốn thực hiện thao tác này?")) return;
                    res = await fetch(`${API_BASE}/users/${id}`, { method: "DELETE" });
                    break;
                case 'create':
                    res = await fetch(`${API_BASE}/admin/create-sales`, {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify(data)
                    });
                    break;
                default: break;
            }

            if (res && res.ok) {
                alert("Thao tác thành công!");
                setShowSalesForm(false);
                setEditingSales(null);
                setSalesFormData({ username: "", email: "", password: "", full_name: "", phone: "" });
                refreshData();
            } else {
                const err = await res.json();
                alert("Lỗi: " + (err.detail || "Không thể thực hiện"));
            }
        } catch (e) { alert("Lỗi kết nối server!"); }
    };
    return (
        <div className="admin-container">
            <aside className="admin-sidebar">
                <div className="logo">🚀 Territory System</div>
                <nav className="main-nav">
                    <button className={activeTab === "territories" ? "active" : ""} onClick={() => setActiveTab("territories")}>🗺️ Quản lý Phân vùng</button>
                    <button className={activeTab === "sales" ? "active" : ""} onClick={() => setActiveTab("sales")}>👥 Sales</button>
                </nav>
                <button className="logout-btn" onClick={() => navigate("/")}>Đăng xuất</button>
            </aside>

            <main className="admin-main">
                {/* --- TAB 1: QUẢN LÝ PHÂN VÙNG --- */}
                {activeTab === "territories" && (
                    <div className="tab-content">
                        <div className="zone-mgr-header">
                            <h2>Thiết kế Phân vùng</h2>
                            <button className="btn-primary" onClick={() => setShowTerritoryForm(true)}>➕ Tạo Phân vùng mới</button>
                        </div>

                        <div className="zone-mgr-layout">
                            <div className="district-list">
                                {/* Công cụ tải phường tự động */}
                                <div className="auto-fetch-container" style={{ padding: '15px', marginBottom: '20px', backgroundColor: '#f8f9fa', borderRadius: '8px', border: '1px solid #ddd' }}>
                                    <h5 style={{ marginBottom: '10px', fontSize: '14px', color: '#2c3e50' }}>📥 Tải Phường tự động</h5>
                                    <input 
                                        type="text" 
                                        placeholder="Tên Quận (vd: Quận Cầu Giấy)" 
                                        value={searchDistrict}
                                        onChange={(e) => setSearchDistrict(e.target.value)}
                                        style={{ width: '100%', padding: '8px', marginBottom: '10px', border: '1px solid #ccc', borderRadius: '4px', fontSize: '13px' }}
                                    />
                                    <button 
                                        onClick={handleAutoFetch} 
                                        disabled={isFetching || !selectedTerritoryId}
                                        className="btn-fetch-auto"
                                        style={{ 
                                            width: '100%', padding: '10px', 
                                            backgroundColor: isFetching ? '#ccc' : '#2ecc71', 
                                            color: 'white', border: 'none', borderRadius: '4px',
                                            cursor: isFetching ? 'not-allowed' : 'pointer', fontWeight: 'bold'
                                        }}
                                    >
                                        {isFetching ? "⏳ Đang tải dữ liệu..." : "🚀 Tải toàn bộ Phường"}
                                    </button>
                                    {!selectedTerritoryId && <p style={{ fontSize: '11px', color: '#e74c3c', marginTop: '5px', fontWeight: '500' }}>* Hãy chọn 1 phân vùng để tải vào</p>}
                                </div>

                                <h4>Phân vùng mục tiêu</h4>
                                {territories.map(t => (
                                    <div 
                                        key={t.id} 
                                        className={`dist-item-card ${selectedTerritoryId === t.id ? "selected-active" : ""}`}
                                        onClick={() => setSelectedTerritoryId(t.id)}
                                    >
                                        <div className="dist-info">
                                            <span className="icon">{selectedTerritoryId === t.id ? "🎯" : "📍"}</span>
                                            <span className="name">{t.name}</span>
                                        </div>
                                        <div className="dist-actions">
                                            <span className="count">{t.zone_ids?.length || 0}</span>
                                            <button className="btn-icon-del" onClick={(e) => {
                                                e.stopPropagation();
                                                handleDeleteTerritory(t.id);
                                            }}>🗑️</button>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="zone-display">
                                <div className="map-toolbar">
                                    {isDrawing ? (
                                        <div className="drawing-controls">
                                            <input type="text" placeholder="Tên vùng..." value={newZoneName} onChange={e => setNewZoneName(e.target.value)} />
                                            <button className="btn-success" onClick={saveDrawnZone}>💾 Lưu</button>
                                            <button className="btn-draw" onClick={() => setTempPoints(prev => prev.slice(0, -1))}>↩️ Hoàn tác</button>
                                            <button className="btn-reject" onClick={() => { setIsDrawing(false); setTempPoints([]); }}>🚫 Hủy</button>
                                        </div>
                                    ) : (
                                        <div className="toolbar-info">
                                            {selectedTerritoryId ? (
                                                <button className="btn-draw" onClick={() => {
                                                    setIsDrawing(true);
                                                    setEditingZoneId(null);
                                                    setTempPoints([]);
                                                    setNewZoneName("");
                                                }}>✏️ Vẽ vùng mới cho "{territories.find(t=>t.id===selectedTerritoryId)?.name}"</button>
                                            ) : (
                                                <span className="hint-text">👈 Chọn một phân vùng để quản lý Zones</span>
                                            )}
                                        </div>
                                    )}
                                </div>

                                <div className="map-box">
                                    <MapContainer center={[21.0285, 105.8542]} zoom={13} style={{ height: '450px', width: '100%' }}>
                                        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                                        <MapEvents drawingMode={isDrawing} currentPoints={tempPoints} setCurrentPoints={setTempPoints} />
                                        {isDrawing && tempPoints.length > 0 && (
                                            <>
                                                <Polyline positions={tempPoints} pathOptions={{ color: 'blue', dashArray: '5, 5' }} />
                                                {tempPoints.map((point, idx) => (
                                                    <CircleMarker key={idx} center={point} radius={4} pathOptions={{ color: 'red' }} />
                                                ))}
                                            </>
                                        )}
                                        {!isDrawing && activeZones.map((z, idx) => (
                                            <GeoJSON 
                                                key={`zone-${z.id}-${idx}`} 
                                                data={z.geometry} 
                                                style={{ color: getZoneColor(idx), weight: 2, fillOpacity: 0.3 }}
                                            >
                                                <Popup><strong>{z.name}</strong></Popup>
                                            </GeoJSON>
                                        ))}
                                    </MapContainer>
                                </div>

                                <div className="zone-details-list">
                                    <h3>Zones hiển thị: {activeZones.length} vùng</h3>
                                    {activeZones.length > 0 ? (
                                        <div className="zone-table-container">
                                            <table className="zone-table">
                                                <thead>
                                                    <tr>
                                                        <th>Màu</th>
                                                        <th>Tên Zone</th>
                                                        <th>Hành động</th>
                                                    </tr>
                                                </thead>
                                                <tbody>
                                                    {activeZones.map((z, idx) => (
                                                        <tr key={z.id}>
                                                            <td><div className="color-box" style={{backgroundColor: getZoneColor(idx)}}></div></td>
                                                            <td>{z.name}</td>
                                                            <td>
                                                                <button className="btn-small" onClick={() => {
                                                                    setEditingZoneId(z.id);
                                                                    setNewZoneName(z.name);
                                                                    setIsDrawing(true);
                                                                    setTempPoints([]);
                                                                }}>📍 Vẽ lại</button>
                                                                <button className="btn-small-del" onClick={() => deleteZone(z.id)}>🗑️</button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                </tbody>
                                            </table>
                                        </div>
                                    ) : (
                                        <p className="empty-msg">Chưa có vùng nào được liên kết.</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- TAB 2: QUẢN LÝ SALES --- */}
                {activeTab === "sales" && (
                    <div className="tab-content">
                        <div className="zone-mgr-header">
                            <h2>Quản lý Đội ngũ Sales</h2>
                            <button className="btn-primary" onClick={() => {
                                setEditingSales(null);
                                setSalesFormData({ username: "", email: "", password: "", full_name: "", phone: "" });
                                setShowSalesForm(true);
                            }}>➕ Thêm Sales mới</button>
                        </div>

                        {pendingSales.length > 0 && (
                            <div className="sales-section pending-section">
                                <h3 className="section-title">⏳ Yêu cầu đăng ký đang chờ ({pendingSales.length})</h3>
                                <div className="sales-grid">
                                    {pendingSales.map(s => (
                                        <div key={s.id} className="sales-card pending">
                                            <div className="sales-info">
                                                <strong>{s.full_name || s.username}</strong>
                                                <span>📧 {s.email}</span>
                                                <span>📞 {s.phone || "N/A"}</span>
                                            </div>
                                            <div className="sales-btns">
                                                <button className="btn-approve" onClick={() => handleSalesAction('approve', s.id)}>Duyệt</button>
                                                <button className="btn-reject" onClick={() => handleSalesAction('reject', s.id)}>Từ chối</button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        <div className="sales-section">
                            <h3 className="section-title">👥 Danh sách Sales chính thức ({salesList.length})</h3>
                            <div className="zone-table-container">
                                <table className="zone-table">
                                    <thead>
                                        <tr>
                                            <th>Username</th>
                                            <th>Họ tên</th>
                                            <th>Email</th>
                                            <th>Điện thoại</th>
                                            <th>Thao tác</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {salesList.map(s => (
                                            <tr key={s.id}>
                                                <td><strong>{s.username}</strong></td>
                                                <td>{s.full_name}</td>
                                                <td>{s.email}</td>
                                                <td>{s.phone}</td>
                                                <td>
                                                    <button className="btn-small" onClick={() => {
                                                        setEditingSales(s);
                                                        setSalesFormData({
                                                            username: s.username,
                                                            email: s.email,
                                                            password: "********",
                                                            full_name: s.full_name,
                                                            phone: s.phone
                                                        });
                                                        setShowSalesForm(true);
                                                    }}>📝 Sửa</button>
                                                    <button className="btn-small-del" onClick={() => handleSalesAction('delete', s.id)}>🗑️ Xóa</button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                )}
            </main>

            {/* MODALS PHẢI NẰM NGOÀI MAIN CONTENT ĐỂ KHÔNG BỊ ẢNH HƯỞNG BỞI CSS LAYOUT */}
            {showTerritoryForm && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <h3>Tạo Phân vùng</h3>
                        <input type="text" placeholder="Tên phân vùng..." value={newTerritoryName} onChange={e => setNewTerritoryName(e.target.value)} />
                        <div className="modal-btns">
                            <button onClick={handleCreateTerritory} className="btn-success">Lưu</button>
                            <button onClick={() => setShowTerritoryForm(false)}>Hủy</button>
                        </div>
                    </div>
                </div>
            )}

            {showSalesForm && (
                <div className="modal-overlay">
                    <div className="modal-content sales-modal">
                        <h3>{editingSales ? "Chỉnh sửa Sales" : "Tạo tài khoản Sales mới"}</h3>
                        <div className="form-grid">
                            <div className="form-group">
                                <label>Username</label>
                                <input 
                                    type="text" 
                                    disabled={!!editingSales}
                                    value={salesFormData.username} 
                                    onChange={e => setSalesFormData({...salesFormData, username: e.target.value})}
                                />
                            </div>
                            <div className="form-group">
                                <label>Email</label>
                                <input 
                                    type="email" 
                                    value={salesFormData.email} 
                                    onChange={e => setSalesFormData({...salesFormData, email: e.target.value})}
                                />
                            </div>
                            {!editingSales && (
                                <div className="form-group">
                                    <label>Mật khẩu</label>
                                    <input 
                                        type="password" 
                                        value={salesFormData.password} 
                                        onChange={e => setSalesFormData({...salesFormData, password: e.target.value})}
                                    />
                                </div>
                            )}
                            <div className="form-group">
                                <label>Họ và Tên</label>
                                <input 
                                    type="text" 
                                    value={salesFormData.full_name} 
                                    onChange={e => setSalesFormData({...salesFormData, full_name: e.target.value})}
                                />
                            </div>
                            <div className="form-group">
                                <label>Số điện thoại</label>
                                <input 
                                    type="text" 
                                    value={salesFormData.phone} 
                                    onChange={e => setSalesFormData({...salesFormData, phone: e.target.value})}
                                />
                            </div>
                        </div>
                        <div className="modal-btns">
                            <button 
                                onClick={() => handleSalesAction(editingSales ? 'update' : 'create', editingSales?.id, salesFormData)} 
                                className="btn-success"
                            >
                                {editingSales ? "Cập nhật" : "Tạo tài khoản"}
                            </button>
                            <button onClick={() => setShowSalesForm(false)}>Hủy</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
